#!/usr/bin/env python3
"""Hourly station product from logger dumps (rules in /app/docs)."""
import json
import math
import os
import re
import sys
from datetime import datetime, timezone
from fractions import Fraction

QUANTITIES = ("temp", "rh", "pres", "wspd", "wdir", "rain")

RANGES = {
    "temp": (-50, 60), "rh": (0, 100), "pres": (870, 1085),
    "wspd": (0, 60), "wdir": (0, 360), "rain": (0, 5000),
}

DIRECTIVE = re.compile(r"^#[ \t]*([a-z]+):(.*)$")
MISSING_NUM = re.compile(r"^[+-]?9999(\.0*)?$")


def _fr(s):
    return Fraction(s)


def converter(q, unit):
    """Return a function converting a Fraction to the canonical unit, or None."""
    if q == "temp":
        if unit == "degC":
            return lambda v: v
        if unit == "degF":
            return lambda v: (v - 32) * 5 / 9
        if unit == "K":
            return lambda v: v - _fr("273.15")
    elif q == "rh":
        if unit == "pct":
            return lambda v: v
        if unit == "frac":
            return lambda v: v * 100
    elif q == "pres":
        f = {"hPa": "1", "kPa": "10", "inHg": "33.8638866667",
             "mmHg": "1.33322387415"}.get(unit)
        if f is not None:
            f = _fr(f)
            return lambda v: v * f
    elif q == "wspd":
        if unit == "ms":
            return lambda v: v
        if unit == "kmh":
            return lambda v: v / _fr("3.6")
        if unit == "kn":
            return lambda v: v * 1852 / 3600
        if unit == "mph":
            return lambda v: v * _fr("0.44704")
    elif q == "wdir":
        if unit == "deg":
            return lambda v: v
    elif q == "rain":
        if unit == "mm":
            return lambda v: v
        if unit.startswith("tips:"):
            try:
                s = _fr(unit[5:])
            except (ValueError, ZeroDivisionError):
                return None
            return lambda v: v * s
    return None


CANON = {"temp": "degC", "rh": "pct", "pres": "hPa", "wspd": "ms",
         "wdir": "deg", "rain": "mm"}


def parse_tz(s):
    s = s.strip()
    if s == "Z":
        return 0
    m = re.match(r"^([+-])(\d{1,2}):?(\d{2})$", s)
    if not m:
        return 0
    off = int(m.group(2)) * 3600 + int(m.group(3)) * 60
    return -off if m.group(1) == "-" else off


def parse_logger_time(s):
    s = s.strip().replace("T", " ", 1)
    d = datetime.strptime(s, "%Y-%m-%d %H:%M:%S")
    return int(d.replace(tzinfo=timezone.utc).timestamp())


def parse_ref(s):
    d = datetime.strptime(s.strip(), "%Y-%m-%dT%H:%M:%SZ")
    return int(d.replace(tzinfo=timezone.utc).timestamp())


def parse_value(field, conv, q):
    """Return converted Fraction reading or None."""
    f = field.strip()
    if f == "" or f == "---" or f.lower() == "nan" or MISSING_NUM.match(f):
        return None
    try:
        v = _fr(f)
    except (ValueError, ZeroDivisionError):
        return None
    v = conv(v)
    lo, hi = RANGES[q]
    if v < lo or v > hi:
        return None
    return v


def read_dump(path):
    with open(path, "rb") as fh:
        raw = fh.read()
    text = raw.decode("utf-8")
    if text.startswith("\ufeff"):
        text = text[1:]
    hdr = {}
    columns = None
    units = dict(CANON)
    rows = []  # (logger_seconds, {q: Fraction or None})
    syncs = []  # (logger_seconds, ref_seconds)
    for line in text.split("\n"):
        if line.endswith("\r"):
            line = line[:-1]
        if line.strip() == "":
            continue
        if line[0] == "#":
            m = DIRECTIVE.match(line)
            if not m:
                continue
            key, val = m.group(1), m.group(2).strip()
            if key in ("station", "upload", "interval", "tz"):
                hdr.setdefault(key, val)
            elif key == "columns":
                columns = [c.strip() for c in val.split(",")]
                hdr.setdefault("columns", columns)
            elif key == "units":
                for pair in val.split():
                    if "=" in pair:
                        k, u = pair.split("=", 1)
                        if k in CANON and converter(k, u) is not None:
                            units[k] = u
            elif key == "sync":
                lg = rf = None
                for part in val.split():
                    if part.startswith("logger="):
                        lg = part[7:]
                    elif part.startswith("ref="):
                        rf = part[4:]
                # logger time contains a space in the "YYYY-MM-DD HH:MM:SS" form
                m2 = re.search(r"logger=(\d{4}-\d\d-\d\d[ T]\d\d:\d\d:\d\d)", val)
                m3 = re.search(r"ref=(\d{4}-\d\d-\d\dT\d\d:\d\d:\d\dZ)", val)
                if m2 and m3:
                    syncs.append((parse_logger_time(m2.group(1)), parse_ref(m3.group(1))))
            continue
        if columns is None:
            continue
        fields = [x.strip() for x in line.split(",")]
        vals = {}
        t = None
        for name, field in zip(columns, fields):
            if name == "time":
                t = parse_logger_time(field)
            elif name in CANON and name not in vals:
                vals[name] = parse_value(field, converter(name, units[name]), name)
        if t is None:
            continue
        rows.append((t, vals))
    return hdr, rows, syncs


def floor_div(a, b):
    return a // b


def main(indir, outfile):
    stations = {}  # id -> dict
    names = sorted(n for n in os.listdir(indir)
                   if n.endswith(".log") and os.path.isfile(os.path.join(indir, n)))
    for n in names:
        hdr, rows, syncs = read_dump(os.path.join(indir, n))
        if "station" not in hdr:
            continue
        sid = hdr["station"]
        upload = int(hdr.get("upload", "0"))
        tz = parse_tz(hdr.get("tz", "Z"))
        st = stations.setdefault(sid, {"interval": None, "samples": {}, "syncs": {}})
        if st["interval"] is None and "interval" in hdr:
            st["interval"] = int(float(hdr["interval"]))
        for lg, rf in syncs:
            t = lg - tz
            cur = st["syncs"].get(t)
            if cur is None or upload >= cur[0]:
                st["syncs"][t] = (upload, rf - t)
        for lg, vals in rows:
            t = lg - tz
            cur = st["samples"].get(t)
            if cur is None or upload >= cur[0]:
                st["samples"][t] = (upload, vals)

    result = []
    for sid in sorted(stations):
        st = stations[sid]
        if not st["samples"]:
            continue
        interval = st["interval"] or 3600
        pts = sorted((t, o) for t, (_, o) in st["syncs"].items())

        def offset(t):
            if not pts:
                return 0
            if t <= pts[0][0]:
                return pts[0][1]
            if t >= pts[-1][0]:
                return pts[-1][1]
            lo, hi = 0, len(pts) - 1
            while hi - lo > 1:
                mid = (lo + hi) // 2
                if pts[mid][0] <= t:
                    lo = mid
                else:
                    hi = mid
            t1, o1 = pts[lo]
            t2, o2 = pts[hi]
            if t == t1:
                return o1
            return o1 + ((o2 - o1) * (t - t1)) // (t2 - t1)

        recs = []
        for t, (_, vals) in st["samples"].items():
            recs.append((t + offset(t), t, vals))
        recs.sort(key=lambda r: (r[0], r[1]))

        def hour_of(c):
            return -((-c) // 3600) * 3600

        first_h = hour_of(recs[0][0])
        last_h = hour_of(recs[-1][0])
        hours = {}
        for h in range(first_h, last_h + 1, 3600):
            hours[h] = {q: {"vals": [], "n": 0} for q in QUANTITIES}
            hours[h]["_vec"] = [0.0, 0.0, 0]

        prev_rain = None  # (corrected, value)
        for c, t, vals in recs:
            h = hours[hour_of(c)]
            for q in QUANTITIES:
                v = vals.get(q)
                if v is None:
                    continue
                h[q]["n"] += 1
                if q == "rain":
                    inc = None
                    if prev_rain is not None and (c - prev_rain[0]) * 2 <= 5 * interval:
                        inc = v - prev_rain[1] if v >= prev_rain[1] else v
                    prev_rain = (c, v)
                    h[q]["vals"].append(float(inc) if inc is not None else 0.0)
                else:
                    h[q]["vals"].append(float(v))
            d = vals.get("wdir")
            s = vals.get("wspd")
            if d is not None and s is not None and s > 0:
                a = math.radians(float(d))
                h["_vec"][0] += math.sin(a)
                h["_vec"][1] += math.cos(a)
                h["_vec"][2] += 1

        expected = 3600 // interval if 3600 % interval == 0 else 3600 / interval
        out_hours = []
        for hs in sorted(hours):
            h = hours[hs]
            entry = {"hour": datetime.fromtimestamp(hs, timezone.utc).strftime("%Y-%m-%dT%H:00:00Z")}
            for q in QUANTITIES:
                n = h[q]["n"]
                value = None
                if n * 4 >= expected * 3 and n > 0:
                    if q == "wdir":
                        sx, sy, cnt = h["_vec"]
                        if cnt > 0 and math.hypot(sx, sy) > 1e-9:
                            ang = math.degrees(math.atan2(sx, sy)) % 360.0
                            value = round(ang, 2)
                            if value >= 360:
                                value = 0.0
                    elif q == "rain":
                        value = round(math.fsum(h[q]["vals"]), 2)
                    else:
                        value = round(math.fsum(h[q]["vals"]) / n, 2)
                    if value is not None:
                        value = value + 0.0
                        if value == 0:
                            value = 0.0
                entry[q] = {"value": value, "n": n}
            out_hours.append(entry)
        result.append({"station": sid, "interval_s": interval, "hours": out_hours})

    with open(outfile, "w", encoding="utf-8") as fh:
        json.dump({"stations": result}, fh, indent=1)
        fh.write("\n")


if __name__ == "__main__":
    if len(sys.argv) != 3:
        sys.stderr.write("usage: hourly.py INPUT_DIR OUTPUT_FILE\n")
        sys.exit(2)
    main(sys.argv[1], sys.argv[2])
